        "黄巣の乱から寝返って唐の節度使となった朱全忠は、「オレのほうが皇帝より強いだろ😡」と、またまた裏切って唐を滅ぼすと、汴州【開封】を都に後梁を建てた。だからといって、朱全忠が中国全体を支配できたわけじゃない。だって、唐末期には全国に40〜50の藩鎮（自立した節度使）があって、軍事権だけじゃなく民政権や財政権も握って半独立になり、唐の言うことさえ全然聞かなかった😅。そんな連中が、「ハイそうですか」と朱全忠の言うことを聞くわけないでしょ。結局、藩鎮が国内でバラバラに分裂している状態は、何も変わらなかったんだよ。",
