      "id": "c05-l16-p01-004",
      "title": "経済発展と形勢戸",
      "body": [
        "五代十国時代には中国の社会が大きく変化したよ。各地にバラバラに分立した藩鎮（節度使）は、自分の国を強くするために領内の産業、特に農地の開発や治水事業などをやったから、長江流域を中心に農業が発展し始めた。さらに、黄河と大運河の接点にあたる汴州【開封】が都になったことで、江南地方から華北への物流が盛んになり、江南地方の経済的な重要性が大きくなった。",
        "そして、経済発展によって金持ちとなった連中は、唐後半に税制が両税法となり土地私有が認められたこともあって、土地に投資した。こうして現れた新興地主は、私有地（荘園）のなかで佃戸と呼ばれる農奴のような小作人を使い、地域社会での権力を強めるとともに、藩鎮を支配する武将とも手を組んだ。この新興地主が形勢戸だ。一方で、唐後半期から衰え始めていた貴族階級は五代十国時代に完全に没落した。だって「武力が強ければエライ！」っていう武断政治の時代だから、貴族たちは戦乱のなかで土地を守ることさえできなかったんだ。"
      ],
