      "id": "c05-l16-p03-004",
      "title": "江南の開発と人口の移動",
      "body": [
        "以後、金に対抗して南宋は江南の開発を進めたから、中国経済の中心は長安や洛陽などを中心とした華北から、江蘇・浙江などの南方に移動した。この経済発展は、金の支配を嫌った漢民族が江南に移住して、華北の進んだ技術が江南に導入されたことも背景だよ。そして、南宋時代には中国の南北の人口が逆転して、南のほうが多くなった。江南が発展したから、華北を失っても南宋は滅びなかったんだよ。"
      ],
