      "id": "c05-l16-p04-004",
      "title": "西夏の建国と宋との関係",
      "body": [
        "チベット系タングート族は、中国からオアシスの道（シルクロード）に抜ける河西回廊をおさえて勢力を拡大すると、1038年に李元昊が皇帝を称して興慶府を都に定め、国号を大夏とした。普通は中国側から見た西夏という名前で呼ばれるね。こうして北宋時代には、北宋・キタイ・西夏の3国が国境を接して争ったんだ。",
        "李元昊は中国に対抗して西夏文字など独自の文化を育てるとともに、軍事力を強化して北宋に攻め込むと、慶暦の和約を結んだよ。ただ、和約を結んだあと西夏はたびたび宋を攻撃した。そして金がキタイと北宋を滅ぼしたのち、西夏は金と友好関係を維持して、東西交易の利益を背景に繁栄したよ。ただ、モンゴルの登場で状況が変わり、チンギス＝ハン（カン）によってあっけなく滅ぼされてしまったんだ。"
      ],
