      "id": "c05-l17-p01-004",
      "title": "オゴデイの即位とカラコルム",
      "body": [
        "チンギス＝ハンが亡くなると、その遺産と軍団は末子のトゥルイが受け継いだんだけど、クリルタイで即位したのは第3子のオゴデイ【オゴタイ】だった。ただ、この時点ではトゥルイのほうが持っている軍団も財産も圧倒的に多かった。オゴデイの即位は、ちょっと陰謀のニオイがするね……😅。",
        "即位してすぐに、オゴデイはトゥルイと一緒に金を滅ぼしたんだけど、遠征の帰りにトゥルイが病死した😨。こうして、まんまと帝国の支配権を握ったオゴデイは、モンゴル高原の真ん中に中国風の都カラコルム【和林】を建設し、さらに全土に向けて駅伝制【ジャムチ】を整備する大事業を開始して、カラコルムを中心とする支配体制をつくると、帝国全体の皇帝の称号としてカアン（大ハーン）を名乗った😆。他の王族が名乗る「ハン」とは違うからね。"
      ],
