      "id": "c05-l17-p01-009",
      "title": "各地のハン国の展開",
      "body": [
        "では、各地のハン国を見ていくよ。チャガタイ家は、中央アジアのアルマリクを都にチャガタイ＝ハン国【チャガタイ＝ウルス】を形成し、カイドゥの乱ののち、オゴデイ家の勢力（オゴデイ＝ハン国とも呼ばれる）も吸収した。その後、14世紀には東西に分裂して、このうち西チャガタイ＝ハン国からティムールが登場するよ！　ジョチ家は、バトゥの遠征で中央アジアから黒海北岸までを制圧し、サライを都にキプチャク＝ハン国【ジョチ＝ウルス】を形成した。支配下のトルコ系遊牧民にイスラーム教徒が多かったから、14世紀のウズベク＝ハン時代にはイスラーム教を受容したよ。15世紀には、支配下のロシア諸侯のなかからモスクワ大公国が自立するね。最後にフレグ家は、西アジアにイル＝ハン国【フレグ＝ウルス】を形成したよ。フレグは、西アジアを制圧したのちにエジプトに遠征したけど、マムルーク朝に負けちゃった😅。また、初期にはネストリウス派を保護し、支配地をめぐるキプチャク＝ハン国との対立からヨーロッパに接近を図ったけど、のちに全盛期のガザン＝ハンがイスラーム教に改宗したよ。この時代のイラン人宰相ラシード＝アッディーン【ラシード＝ウッディーン】による『集史』は史上初のユーラシア世界史で、モンゴルの重要な史料だね。"
      ],
