      "id": "c05-l17-p03-004",
      "title": "モンゴルを訪れた宣教師",
      "body": [
        "帝国支配のもとで交通路が発達すると、人の移動も活発になった。特に13世紀は、ヨーロッパで十字軍がおこなわれていた時代だから、教皇や国王たちは、イスラーム教徒を挟み撃ちしようとモンゴルに外交使節を送った。だから、カトリックの宣教師（みんなフランチェスコ会だ）が次々とやってくるよ。教皇インノケンティウス4世の使節としてやってきたプラノ＝カルピニはグユクに親書を渡し、フランス王ルイ9世が派遣したルブルックはカラコルムでモンケに謁見して、十字軍への協力を要請した。でも、まんまと断られたけどね😅。その後やってきたモンテ＝コルヴィノは初代の大都大司教となり、中国で初めてカトリックを布教したよ。"
      ],
