      "id": "c05-l18-p02-004",
      "title": "琉球とマラッカの繁栄",
      "body": [
        "そして、明への朝貢貿易で特に発展したのが、<span class=\"source-bold\">琉球とマラッカ</span>だよ。15世紀半ばに中山王<span class=\"source-bold\">尚巴志</span>が統一した<span class=\"source-bold\">琉球王国</span>は、明に朝貢して冊封を受けると、朝貢貿易で絹や陶磁器などの中国物産を持ち帰り、日本や東南アジア諸国と取引して繁栄した。琉球王国の位置は東シナ海と南シナ海の境目で、アジア海域のどこでも交易できるから、中継貿易にはもってこいの場所だ。しかも、琉球は冊封体制の頂点となる「礼」の秩序をきちんと守ったから、「<span class=\"source-bold\">守礼の邦</span>」として朝廷にもめちゃくちゃ評価されて、勘合（通行証）なしで朝貢できる特権をもらったんだよ。",
        "一方、<span class=\"source-bold\">マラッカ王国</span>は、鄭和の南海遠征に協力して発展した国だよ。15世紀前半、北からタイの<span class=\"source-bold\">アユタヤ朝</span>から圧迫を受けたマラッカは、明に朝貢して鄭和の南海遠征に港を提供した。鄭和も「ここは遠征の基地にちょうどいい」と思って艦隊の拠点を置き、アユタヤ朝に「マラッカをイジメるのはやめなさい」と圧力をかけた。こうしてマラッカはアユタヤ朝から自立したんだ。さらに王朝をムスリム教に改宗して東南アジア初の本格的なイスラーム国家となるとムスリム商人も多数来航し、中国の物産、マルク諸島【モルッカ諸島】の香辛料、インドの綿織物などが集まる東南アジア最大の貿易拠点になった。こんなふうに、海禁政策のもとでも、朝貢貿易はむちゃくちゃ発展していたんだよ。"
      ],
