        "そして、明の財政難に追い打ちをかけたのが、末期に重なった対外危機だよ😨。モンゴル人の将軍ボハイの反乱や南部で起きた楊応龍（貴州省の土司）の反乱などもあるけど、明を危機的状況に追い込んだのは豊臣秀吉の朝鮮侵略だ。この事件は、日本では文禄・慶長の役、朝鮮では壬辰・丁酉倭乱と呼ばれるね。日本の統一を果たした豊臣秀吉は、「次は明を征服する😤」として、明の朝貢国だった朝鮮に「明に攻め込むから、手伝え！」と言ったら、まんまと断られた。怒った秀吉は朝鮮に出兵し、1回目の遠征では、最新型の火砲を駆使してわずか1カ月で漢城（現在のソウル）を占領したよ。でも、宗主国である明が朝鮮に援軍を送ってきて、さらに朝鮮水軍の李舜臣は亀船【亀甲船】を使って海上をおさえた。",
