      "id": "c05-l18-p04-013",
      "title": "地丁銀と人口の増加",
      "body": [
        "そしてもう一つ、清では明以来の一条鞭法にかえて、新しい税制である<span class=\"source-bold\">地丁銀</span>が導入された。ここは背景もしっかりおさえてね！　中国を平定したのち、康熙帝は江南や華南の状況を自ら視察したんだけど、このとき、税金逃れのために戸籍に登録しない人が多いことにショックを受けた😨。そこで、課税に対する人びとの不安や不満を消すために、康熙帝の即位50周年にあたる1711年の人口で人頭税の額を固定し、これ以後に増加した人口については盛世滋生人丁として、課税しないことにすると、最終的には地域ごとの人頭税の総額を計算して、その分、ちょっとずつ土地税を値上げした。つまり、人頭税を土地税の中に入れちゃったってことね。こうして中国では<span class=\"source-bold\">人頭税が廃止</span>され、地税に一本化されたよ。これが教科書で「丁銀（人頭税）を地銀（土地税）に繰り込んで、一括して銀納する」って説明される地丁銀だよ。「人頭税がないから、家族の人数が増えても大丈夫😁」と、人びとは安心して子どもを産めるようになった。だって、農村では子どもが重要な労働力だもん。こうして18世紀以降の清では、爆発的に人口が増えたんだ。"
      ],
      "plainBody": [
        "そしてもう一つ、清では明以来の一条鞭法にかえて、新しい税制である地丁銀が導入された。ここは背景もしっかりおさえてね！　中国を平定したのち、康熙帝は江南や華南の状況を自ら視察したんだけど、このとき、税金逃れのために戸籍に登録しない人が多いことにショックを受けた😨。そこで、課税に対する人びとの不安や不満を消すために、康熙帝の即位50周年にあたる1711年の人口で人頭税の額を固定し、これ以後に増加した人口については盛世滋生人丁として、課税しないことにすると、最終的には地域ごとの人頭税の総額を計算して、その分、ちょっとずつ土地税を値上げした。つまり、人頭税を土地税の中に入れちゃったってことね。こうして中国では人頭税が廃止され、地税に一本化されたよ。これが教科書で「丁銀（人頭税）を地銀（土地税）に繰り込んで、一括して銀納する」って説明される地丁銀だよ。「人頭税がないから、家族の人数が増えても大丈夫😁」と、人びとは安心して子どもを産めるようになった。だって、農村では子どもが重要な労働力だもん。こうして18世紀以降の清では、爆発的に人口が増えたんだ。"
      ],
