      "id": "c05-l18-p04-018",
      "title": "朝鮮と小中華意識",
      "body": [
        "朝鮮では、豊臣秀吉の朝鮮侵略のときに援軍を送ってくれた明に対する恩義の気持ちが強くなる一方、北にいる女真族を「しょせん北方の野蛮人だ😠」と思っていた。そしたら女真族が後金【アイシン】を建て、さらには清と改称して朝鮮に攻めてきた😨。こうして、清に敗れた朝鮮は仕方なく清に朝貢したんだけど、ウラでは「この野蛮人め！」って思っていた。そして明が滅んだあと、「清のような“夷（野蛮人）”に汚された中国には、中華はない😡。明を継承する正統な中華文明は朝鮮にある！」という「<span class=\"source-bold\">小中華</span>」の意識をもって、ことさらに儒教的な儀礼を強調するようになったんだ。"
      ],
