      "id": "c05-l19-p02-007",
      "title": "北ベトナムの独立と李朝",
      "body": [
        "北ベトナムは「海の道」から少し奥まったところに位置していて、ほかの国がほしがるような特産物もあまりなかったから、海上交易は発展しなかったんだけど、10世紀に唐が滅んで五代十国時代になると、北ベトナムは中国王朝の支配を撃退して独立した。ただ、初期にあったいくつかの政権はあっという間に潰れてしまって、王朝交代が続いたんだ。そして11世紀初めに、李公蘊がハノイを都に李朝を開き、国号を「大越【ダイベト】（国）」（ダイベトは“大越”のベトナム語読み）とした。ここから黎朝までは、国号が「大越（国）」、都は現在のハノイだよ！　中国支配ルートから外れていた李朝は、紅河（ホン川）デルタを開拓して、農業を中心とする国をつくった。そして、北宋に朝貢して大乗仏教・儒教・道教など中国文化を学び、中国の官僚制度や科挙も導入したよ。"
      ],
      "plainBody": [
        "北ベトナムは「海の道」から少し奥まったところに位置していて、ほかの国がほしがるような特産物もあまりなかったから、海上交易は発展しなかったんだけど、10世紀に唐が滅んで五代十国時代になると、北ベトナムは中国王朝の支配を撃退して独立した。ただ、初期にあったいくつかの政権はあっという間に潰れてしまって、王朝交代が続いたんだ。そして11世紀初めに、李公蘊がハノイを都に李朝を開き、国号を「大越【ダイベト】（国）」（ダイベトは“大越”のベトナム語読み）とした。ここから黎朝までは、国号が「大越（国）」、都は現在のハノイだよ！　中国支配ルートから外れていた李朝は、紅河（ホン川）デルタを開拓して、農業を中心とする国をつくった。そして、北宋に朝貢して大乗仏教・儒教・道教など中国文化を学び、中国の官僚制度や科挙も導入したよ。"
      ],
