      "id": "c05-l19-p04-005",
      "title": "コンバウン朝とラタナコーシン朝",
      "body": [
        "18世紀半ばになると、ビルマでは内陸部から現れたアラウンパヤーがコンバウン朝【アラウンパヤー朝】を建て、モン人の勢力や清朝の侵攻を退けて勢力を拡大すると、さらにタイにも侵攻してアユタヤ朝を滅ぼした。こうして現在のビルマ（ミャンマー）とほぼ同じ領域を支配して、半島部の覇権国になったんだ。ただ、このあとインドのアッサム地方に攻め込んだら、インド支配を固めていたイギリスと戦争になった😨。このイギリス＝ビルマ戦争【ビルマ戦争】に敗れて、コンバウン朝はイギリスに滅ぼされたんだ。",
        "一方、アユタヤ朝が崩壊した後のタイでは、アユタヤ朝の武将たちがコンバウン朝に清が攻め込んだのに乗じて自立し、そのなかから現れたチャクリ【ラーマ1世】がラタナコーシン朝を建てて、バンコクを都にしたよ。建国後はビルマのコンバウン朝の侵攻を撃退し、上座部仏教を支柱にした国づくりに努めたんだ。"
      ],
