      "id": "c05-l19-p04-006",
      "title": "黎朝の南進と南北分裂",
      "body": [
        "陳朝が農民の反乱で滅亡すると（胡朝の成立）、「陳朝を復活させる！」という口実で明の永楽帝が攻めてきて、ベトナムは明の支配を受けたんだ。ただ、すぐに黎利が明を撃退して独立を回復して、黎朝ができたよ。黎朝は、中国風の官僚制度や儒学を導入して国家体制を整備すると、南部への進出をすすめてチャンパーを制圧した。こうして、ほぼ現在のベトナムと同じ地域まで支配を拡大したんだ。",
        "ただ、16世紀ころから軍人の力が強まって国内が分裂した。北部では鄭氏がハノイを拠点に実権を握り、南部では鄭氏に対抗して阮氏がフエで自立、ベトナムは鄭氏の大越国（北部）と阮氏の広南国（南部）に分裂しちゃった😨。どちらの勢力もポルトガルやオランダ、さらには朱印船で来航する日本人とも交易していたから、中国で清朝が鄭成功を孤立させるために遷界令を発すると、中国沿岸から逃れた華人たちがベトナム南部に逃げてきて、都市を建設し始めたんだ。"
      ],
